import logging

from ute_common_converter.to_list import to_int_list
from ute_common_converter.to_number import to_int
from ute_common_sshforwarder.forwarder import Forwarder

from .common import WTSCommonInterface
from ..wts.state_machine import WTSStateMachine
from ..luaconfiggenerator.luaconfgenerator import LuaConfigGenerator
from ..filecollector.filecollector import FileCollector
from ..wts.iphyvalidator import IphyConfigValidator


class WtsInterface(WTSCommonInterface):

    def start_wts_applications(self, egate_port=20000, edaemon_ports=(10000, 30000), cfg_file=None, suite_file=None,
                               timeout=None, tool_dir=None, lua_dirs=(), ext=(), **kwargs):
        """Start WTS environment including egate and edaemons.

        :param integer egate_port:    Egate process port.
        :param list    edaemon_ports: List of edaemon process ports. Edaemon application will be started on each port.
                                      Single value is supported.
        :param string  cfg_file:      Path to lua file with egate configuration.
        :param string  suite_file:    Path to xml file with egate test suite configuration.
        :param         timeout:       Timeout for the configuration operation. Default is 60 seconds.
                                      Can be specified in human format like 5s, 10minutes, 1min 5s.
        :param string  tool_dir:      Path to directory where WTS binaries are available.
        :param list    lua_dirs:      One or more directory paths where lua scripts are stored.
        :param list    ext:           Extension library or extension class. Single value possible.


        """
        alias = kwargs.get('alias')
        timeout = self._to_secs(timeout)
        edaemon_ports = self._to_port_list(edaemon_ports)

        ssh_client = self._create_ssh_client_for_alias(alias)
        telnet_client = self._create_telnet_client_for_alias(egate_port, alias)

        egate = self._create_egate(egate_port, ssh_client, telnet_client, tool_dir, lua_dirs)
        edaemons = self._create_edaemons(edaemon_ports, ssh_client, tool_dir)
        self._store_wts(egate, edaemons, cfg_file, suite_file, timeout, alias)
        self._notify_extenders(egate, alias, ext)
        self.wts_store.get(alias).start()

    def start_wts_services(self, timeout=None, retry=0, check_version=True, **kwargs):
        """Start WTS services configured by lua file.

        :param timeout: Timeout for the configuration operation. Default is 60 seconds.
                        Can be specified in human format like 5s, 10minutes, 1min 5s.
        :param retry: Number of retries to start wts services.
        :param check_version: Enable/Disable version checking between WTS binaries.


        :note: This keyword is equal with egate command: start
        """
        timeout = self._to_secs(timeout)
        alias = kwargs.get('alias')
        egate = self.wts_store.get(alias).egates[0]
        retry = int(retry)
        if retry <= 0:
            egate.start_services(timeout, check_version)
        if retry > 0:
            egate.retry_services(timeout, retry, check_version)

    def configure_ssh_connection_for_wts(self, host_ip=None, ssh_username=None, ssh_password=None, ssh_port=None, ssh_prompt=None, **kwargs):
        """Configure parameters of SSH connection to host where WTS is available.

        :param string  host_ip:      Host IP where WTS application is available.
        :param string  ssh_username: SSH username required by host.
        :param string  ssh_password: SSH password required by host.
        :param integer ssh_port:     Port where SSH service is available on the host.
        :param string  prompt:       SSH prompt available after logging in.


        :note: `Configure ssh connection for wts`_ is only valid for WTS keywords.
               Please use `Reset wts ssh connection parameters`_ to back to default values.
        """
        alias = kwargs.get('alias')
        self._configure_ssh_connection_for_alias(host_ip, ssh_username, ssh_password, ssh_port, ssh_prompt, alias)

    def configure_enb_ssh_connection_for_wts(self, enb_ip=None,  enb_username=None, enb_password=None, enb_prompt=None, **kwargs):
        """Configure parameters of SSH connection to eNB.

        :param string enb_ip:         IP address of FSM e.g. 192.168.255.1.
        :param string enb_username:       SSH username available on FSM.
        :param string enb_password:   SSH password available on FSM.
        :param string enb_prompt:     SSH prompt available after logging in.


        :note: Result of this keyword is used in `Generate lua configuration for wts`_ keyword.
        """
        alias = kwargs.get('alias')
        self._configure_ssh_connection_to_enb(enb_ip, enb_username, enb_password, enb_prompt, alias)

    def reset_wts_ssh_connection_parameters(self, **kwargs):
        """Reset SSH connection parameters specified by `Configure ssh connection for wts`_ keyword.


        """
        alias = kwargs.get('alias')
        self._init_connection_parameters(alias)

    def stop_and_collect_wts_logs(self, unzip=None, subdirectory=None, **kwargs):
        """Stops WTS application and collect all logs generated by WTS binaries.

        :param boolean unzip:        Flag indicating whether collected logs should be extracted.
        :param string  subdirectory: Name of folder to create in addition to the normal test result structure.

        This method will download the following files:

        * edaemon.log
        * mme_*.log
        * pgw_*.log
        * sgw_*.log
        * uec_*.log
        * egate.log
        * egate_console.log
        * testline_info.log

        :note: Is not valid for teardown of "Setup Egate" and "Setup Edaemon"

        :note: Format of result directory structure is: TestSuite1/TestSuite2/TestCase/SubFolder.

        :note: testline_info.log will not be available on WTS with versions older than 20170818-1708.WK33.01.
        """
        alias = kwargs.get('alias')
        wts = self.wts_store.get(alias)
        wts.stop()
        self._collect_logs(wts, unzip, subdirectory)
        self.get_testline_info(subdirectory, alias=alias)
        wts.close_all_connections()
        self.wts_store.remove(alias)
        self.notifier.egate_deleted(alias)

    def get_testline_info(self, subdirectory=None, **kwargs):
        """
        Gets and executes get_testline_info.sh from egate

        :param string subdirectory:     Name of folder to create in addition to the normal test result structure.

        :note: If you have called Stop and Collect WTS Logs then you don't have to call this keyword anymore.

        :note: testline_info.log will not be available on WTS with versions older than 20170818-1708.WK33.01.
        """
        alias = kwargs.get('alias')
        client = self._create_ssh_client_for_alias(alias)
        FileCollector(ssh_client=client).get_testline_info(subdirectory)

    def teardown_all_aliases_for_wts(self, **kwargs):
        """Removes all aliases for wts and collects log files

        :note: Is not valid for teardown of "Setup Egate" and "Setup Edaemon"

        """
        for alias_name_wts in self.wts_store.aliases:
            self.stop_and_collect_wts_logs(alias=alias_name_wts)

    def generate_lua_configuration_for_wts(self, config_dir, config_file, enb_index=1, iphy_path=None, **kwargs):
        """ Create lua configuration file for for a given eNB

        :param string config_dir:   Path to directory where new configuration will be stored.
        :param string config_file:  File name for new configuration (file extension is optional).
        :param integer enb_index:   Number of eNB in multienb environment. For first index will be 1, for the second 2.
        :param string iphy_path:    Path to iphy xml configuration file.

        It is possible to change all values via **kwargs** as follow:
        ::

            # Change tac and mcc values
            Generate lua configuration for wts     config_dir=/tmp    config_file=enb     tac=${123}     mcc=4

            # Change uec information
            Generate lua configuration for wts     config_dir=/tmp    config_file=enb     uec_server_ip=10.2.2.2    uec_proxy_ip=10.2.2.1

        It is possible to change SSH PC connection parameters and SSH eNB parameters via separate keywords:

        * `Configure ssh connection for wts`_
        * `Configure enb ssh connection for wts`_

        To find proper settings all three keywords must use same **alias**. You can find more in Robot Framework examples attached to documentation.

        Generated lua configuration file contains a public module with the testline attributes and has the same name as filename.
        It should be preloaded or put in /opt/iphy/latest so that it can be used as a module in a lua file, like in this example:

            require "auto_generated_config"

            edaemon_ip = auto_generated_config.edaemon_ip
            edaemon_port = auto_generated_config.edaemon_port

        :For SBTS builds connecting to Admin, it is possible to change Admin connection via kwargs with additional parameters:
            * **admin_host** (string)      -  BTS IP address. Defaults to 192.168.255.129.
            * **admin_port** (integer)     -  AdminAPI port. Defaults to 443.
            * **admin_username** (string)  -  AdminAPI username. Defaults to Nemuadmin.
            * **admin_password** (string)  -  AdminApi password. Defaults to nemuuser.

        """
        logging.warning("Deprecated since 2.0.0. Reason: "
                        "KW won't be able to generate SCF via ADMIN connection. "
                        "From 2.0.0 user will be required to provide SCF template to be filled. "
                        "SSH SCFC fetch (/ffs/run/config/SCFC_*.xml) will no longer be available. "
                        "Please adjust your TCs to not use ADMIN")
        enb_index = to_int(enb_index)
        alias = kwargs.pop('alias', None)

        admin_params = {'admin_host': kwargs.pop('admin_host', '192.168.255.129'),
                        'admin_port': to_int(kwargs.pop('admin_port', 443)),
                        'admin_username': kwargs.pop('admin_username', 'Nemuadmin'),
                        'admin_password': kwargs.pop('admin_password', 'nemuuser')}

        settings = self._get_connection_settings_for_alias(alias)
        bind_port, forwarder = self._create_forwarder(settings)
        client_settings = self._configure_ssh_connection('127.0.0.1', settings.enb_username, settings.enb_password, bind_port, settings.enb_prompt)
        self._generate_lua_via_tunneled_connection(client_settings, config_dir, config_file, forwarder,
                                                   enb_index, iphy_path, admin_params, settings, kwargs)

    def validate_iphy_config(self, scfc, iphyxml, iphydb=None, **kwargs):
        """Validates iphy configuration consistency.

        :param string scfc:            Path to SCFC file
        :param string iphyxml:         Path to Iphy configuration file
        :param string iphydb:          Path to Iphy DB (iphy_db) file
        |

        :Supported parameters are available via kwargs:
            * **debug**     (boolean) -  enable debug mode
        """
        alias = kwargs.get('alias')
        client = self._create_ssh_client_for_alias(alias)
        validator = IphyConfigValidator(client)
        validator.validate(scfc, iphyxml, iphydb, **kwargs)

    def _store_wts(self, egate, edaemons, cfg_file, suite_file, timeout, alias):
        wts = WTSStateMachine()
        wts.add_egate(egate, cfg_file, suite_file, timeout)
        wts.add_edaemons(edaemons)
        self.wts_store.add(wts, alias)

    def _to_port_list(self, edaemon_ports):
        if not isinstance(edaemon_ports, (list, tuple)):
            edaemon_ports = [edaemon_ports]
        return to_int_list(edaemon_ports)

    def _create_forwarder(self, settings):
        forwarder = Forwarder(settings.ssh_connection_params, settings.ssh_login_params, settings.enb_ip, 22)
        bind_port = forwarder.start()
        return bind_port, forwarder

    def _generate_lua_via_tunneled_connection(self, client_settings, config_dir, config_file, forwarder,
                                              enb_index, iphy_path, admin, settings, kwargs):
        ssh_client = None
        try:
            ssh_client = self._create_ssh_client_from_settings(client_settings)
            LuaConfigGenerator(ssh_client, admin, settings).build_configuration(config_dir, config_file, enb_index, iphy_path, **kwargs)
        finally:
            if ssh_client:
                ssh_client.close()
            forwarder.stop()
